const panel=document.querySelector('.explainer'),scene=document.querySelector('#visual-scene'),buttons=[...document.querySelectorAll('.work-choice')],steps=[...document.querySelectorAll('[data-phase]')],toggle=document.querySelector('#motion-toggle');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let selected=0,phase=0,paused=reduced.matches,timer;
function visual(){if(selected===0)return '<div class="scene-image"><img src="assets/original.jpg" alt=""><img class="edited-layer" src="assets/edited.jpg" alt=""><div class="scan-line"></div><div class="edit-box"></div></div>';if(selected===1)return '<div class="scene-node"><b>≋</b><span>Original writing</span></div><div class="scene-arrow">→</div><div class="scene-node"><b>◇</b><span>AI styling</span></div><div class="scene-arrow">→</div><div class="scene-node risk"><b>⇄</b><span>Privacy ↔ exposure</span></div>';return '<div class="scene-node"><div class="signal-bars"><i></i><i></i><i></i><i></i><i></i></div><span>Sensor inputs</span></div><div class="scene-arrow">→</div><div class="scene-node"><b>⌘</b><span>Learning model</span></div><div class="scene-arrow">→</div><div class="scene-node safe"><b>◷</b><span>Energy + latency</span></div>';}
function schedule(){clearInterval(timer);if(!paused)timer=setInterval(()=>{if(phase<2){phase++;renderPhase();}else{const order=buttons.map(b=>Number(b.dataset.work));choose(order[(order.indexOf(selected)+1)%order.length]);}},4000);}
function renderPhase(){const detailed=selected===0||selected===1||selected===3||selected===4||selected===5;scene.classList.toggle('edits-scene',detailed);scene.setAttribute('aria-hidden',String(!detailed));if(selected===0){scene.innerHTML=window.editsScene(phase);window.bindEditsScene(phase,scene,()=>setPause(true));}if(selected===1||selected===3){scene.innerHTML=window.paperScene(selected,phase);window.bindPaperScene(selected,phase,scene,()=>setPause(true));}if(selected===4){scene.innerHTML=window.quantumScene(phase);window.bindQuantumScene(phase,scene,()=>setPause(true));}if(selected===5){scene.innerHTML=window.sustainScene(phase);window.bindSustainScene(phase,scene,()=>setPause(true));}document.querySelector('.stage-bottom>span').textContent=detailed?'Paper examples and reported results':'Conceptual explainer · not experimental results';document.querySelector('#phase-label').textContent=['THE QUESTION','THE APPROACH','WHY IT MATTERS'][phase];document.querySelector('#phase-title').textContent=works[selected].phases[phase][0];document.querySelector('#phase-description').textContent=works[selected].phases[phase][1];scene.dataset.phase=phase;steps.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===phase)));panel.classList.remove('scene-enter');void panel.offsetWidth;panel.classList.add('scene-enter');}
function choose(i){selected=i;phase=0;buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(Number(b.dataset.work)===i)));document.querySelector('#work-venue').textContent=works[i].venue;document.querySelector('#work-summary').textContent=works[i].summary;document.querySelector('#work-paper').href=works[i].url;scene.innerHTML=visual();renderPhase();setPause(reduced.matches);}
function setPause(value){paused=value;panel.classList.toggle('paused',paused);toggle.textContent=paused?'Play animation':'Pause animation';toggle.setAttribute('aria-pressed',String(paused));schedule();}
buttons.forEach((b,i)=>b.addEventListener('click',()=>{choose(Number(b.dataset.work));if(matchMedia('(max-width:800px)').matches)panel.scrollIntoView({behavior:reduced.matches?'auto':'smooth',block:'start'});}));steps.forEach((b,i)=>b.addEventListener('click',()=>{phase=i;setPause(true);renderPhase();}));toggle.addEventListener('click',()=>setPause(!paused));reduced.addEventListener('change',e=>{if(e.matches)setPause(true)});document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInterval(timer);else schedule()});document.querySelector('.menu').addEventListener('click',function(){const nav=document.querySelector('.links');nav.classList.toggle('open');this.setAttribute('aria-expanded',String(nav.classList.contains('open')))});choose(0);setPause(paused);

